select * from customer_shopping_behavior;

--1).Revenue Analysis--
--Compared total revenue generated by male and female customers.

select gender, sum(purchase_amount) as total_revenue
   from customer_shopping_behavior
   group by gender;
   
--2. Discount & Spending Analysis --
--Identified discount users whose purchase amounts were at or above the overall average
select customer_id, purchase_amount
  from customer_shopping_behavior
  where discount_applied= 'Yes'
  and purchase_amount>= (select avg(purchase_amount) from customer_shopping_behavior)
;

---Product & Rating Analysis--
--3).Ranked  the top 5 products by average review rating.
select item_purchased,
  avg(review_rating) as "Average Product Rating"
  from customer_shopping_behavior
  group by item_purchased
  order by avg(review_rating) desc
  limit 5;

--4.Shipping Analysis--
--Compared average purchase amounts for standard and express shipping.
select * customer_shopping_behavior
select shipping_type,round(avg(purchase_amount),2)
  from customer_shopping_behavior
  where shipping_type in ('Standard','Express')
  group by shipping_type;

--5.Subscription Analysis--
--Compared customer counts, average spending, and total revenue between subscribers.
--and non - subscribers.


select subscription_status,
    count(customer_id) as total_customers,
	round(avg(purchase_amount), 2) as avg_spend,
	round(sum(purchase_amount), 2) as total_revenue
	from customer_shopping_behavior
          group by subscription_status
		  order by total_revenue desc, avg_spend desc;

--6. Discount Dependency Analysis--
--Identified the top 5 products by percentage of purchases with discounts applied.

select item_purchased,
   round(
         100*sum(
                 case when discount_applied = 'Yes' then 1
				 else 0 end)/count(*),2)
				 as discount_rate
				 from customer_shopping_behavior
				 group by item_purchased
				 order by discount_rate desc
				 limit 5;

--7.Customer Segmentation--
--Classified customers into New,,Returning, and Loyal segments based on previous purchases.
with customer_type as
   (select customer_id,previous_purchases,
    case when previous_purchases=1 then 'New'
	     when previous_purchases between 2 and 10 then 'Returning'
		 else'Loyal'
		 end as customer_segment
		 from customer_shopping_behavior)
select customer_segment,
      count(*) as Number_of_Customers
	  from customer_type
	  group by customer_segment;

--Product Popularity Analysis--
--Identified the top 3 most purchased products within each category.
with item_counts as
    ( select category,
	item_purchased,
	count(customer_id) as total_orders,
	row_number() over (partition by category order by count(customer_id) desc) as item_rank
	from customer_shopping_behavior
	group by category, item_purchased
	)
select item_rank, category, item_purchased, total_orders
from item_counts
where item_rank<=3;

--9) Repeat Buyer Analysis--
--Compared subscription_status among customers with more than 5 previous purchases.

select subscription_status,
count(customer_id) as repeated_buyers
from customer_shopping_behavior
where previous_purchases>5
group by subscription_status;

--10) Age Group REvene Analysis--
--Compared total revenue across customer age groups.

select age_group, sum(purchase_amount) as total_revenue
from customer_shopping_behavior
group by age_group
order by total_revenue desc;
	
				 
		 




